def countFixingEdges(n, edges):
    m = len(edges)
    out = [[] for _ in range(n)]
    for i, (a, b) in enumerate(edges):
        out[a].append((b, i))

    def kahn(skip):
        indeg = [0] * n
        for i, (a, b) in enumerate(edges):
            if i != skip:
                indeg[b] += 1
        stack = [v for v in range(n) if indeg[v] == 0]
        removed = [False] * n
        done = 0
        while stack:
            u = stack.pop()
            removed[u] = True
            done += 1
            for v, i in out[u]:
                if i != skip:
                    indeg[v] -= 1
                    if indeg[v] == 0:
                        stack.append(v)
        return done == n, removed

    acyclic, removed = kahn(-1)
    if acyclic:
        return m
    pred = {}
    for i, (a, b) in enumerate(edges):
        if not removed[a] and not removed[b] and b not in pred:
            pred[b] = (a, i)
    cur = next(v for v in range(n) if not removed[v])
    pos = {}
    walk = []
    while cur not in pos:
        pos[cur] = len(walk)
        a, i = pred[cur]
        walk.append(i)
        cur = a
    cycle_edges = walk[pos[cur]:]
    return sum(1 for i in cycle_edges if kahn(i)[0])
